package com.himeros.premium;import com.himeros.shared.CurrentUser;import java.util.*;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/v1/premium")public class PremiumController{private final PremiumService service;private final CurrentUser current;public PremiumController(PremiumService s,CurrentUser c){service=s;current=c;}@GetMapping("/subscription")Map<String,Object> active(){return service.active(current.id()).<Map<String,Object>>map(s->Map.of("active",true,"subscription",s)).orElseGet(()->Map.of("active",false));}}
